INSERT INTO `phong_tro` VALUES (2,'1011',4400000.00,'DA_THUE','điện  nước rẻ\n',44,'Lã Xuân Oai',50,2000.00,40000.00,'data:image/jpeg;base64,|||data:image/jpeg;base64,',5000000.00),(3,'1001',4000000.00,'DA_THUE','',44,'Đình phong phú ',40,3000.00,10000.00,'data:image/jpeg;base64,',10000000.00),(4,'1002',6500000.00,'TRONG','Căn hộ thông tầng 35m² rộng nhất dãy, phù hợp cho gia đình hoặc nhóm bạn. Trang bị bàn ăn, máy nước nóng, tủ lạnh lớn và bếp từ đôi.',44,'Quận 2',35,4000.00,15000.00,'data:image/jpeg;base64,',10000000.00),(5,'1003',5000000.00,'TRONG','Căn studio 28m² ngập tràn ánh sáng tự nhiên với cửa sổ lớn hướng Đông. Nội thất tiện nghi có sofa mini, bàn làm việc và tủ kịch trần sang trọng.',44,'Quận ',28,4000.00,100000.00,'',1000000.00),(12,'1004',7000000.00,'TRONG','Căn hộ thông tầng 35m² rộng nhất dãy, phù hợp cho gia đình hoặc nhóm bạn. Trang bị bàn ăn, máy nước nóng, tủ lạnh lớn và bếp từ đôi.',44,'Quận 1 HCM',30,3000.00,10000.00,'data:image/jpeg;base64,',15000000.00),(13,'1005',10000000.00,'TRONG','Căn hộ mini dạng studio tại tầng 2, căn góc sở hữu 2 mặt thoáng cực kỳ mát mẻ. Phòng được trang bị đầy đủ nội thất cao cấp: Giường nệm, tủ quần áo gỗ sang trọng',44,'Thảo điền ',50,4000.00,20000.00,'data:image/jpeg;base64,',20000000.00),(14,'101',3500000.00,'TRONG','Phòng trọ diện tích 20m² nằm ngay tầng trệt, lối đi riêng không chung đụng chủ. Phòng thiết kế vuông vắn, tường ốp gạch men sạch sẽ, có sẵn kệ bếp đá hoa cương và bồn rửa chén.',50,'dĩ an bình dương',20,2800.00,9000.00,'data:image/jpeg;base64,',2000000.00),(15,'102',4000000.00,'TRONG','Căn phòng tầng 4 rộng 26m² sở hữu tầm nhìn đắt giá ra toàn cảnh thành phố và Landmark. Gác lửng được làm cao ráo, đứng thẳng người thoải mái.',50,'Lê văn việt',28,4000.00,10000.00,'data:image/jpeg;base64,',4000000.00),(16,'103',4000000.00,'TRONG','Phòng lầu 4 rộng 22m² có sẵn máy lạnh, nằm ngay cạnh sân thượng lộng gió. Bước ra cửa là tới máy giặt chung và sân phơi đồ siêu rộng, view ngắm cảnh rất chill.',50,'3 đường 182 ',22,4000.00,10000.00,'data:image/jpeg;base64,',4000000.00),(17,'104',5000000.00,'TRONG','Căn hộ thông tầng 35m² rộng nhất dãy, phù hợp cho gia đình hoặc nhóm bạn. Trang bị bàn ăn, máy nước nóng, tủ lạnh lớn và bếp từ đôi.',50,'Võ Văn Ngân',35,4000.00,40000.00,'data:image/jpeg;base64,',5000000.00),(18,'105',10000000.00,'TRONG',' căn hộ rộng 32m² tại tầng 4 này thiết kế phòng khách và phòng ngủ hoàn toàn tách biệt. Khu vực phòng khách có sofa, tủ lạnh và bếp từ đôi cao cấp',50,'Ngã 4 thủ đức ',32,2000.00,20000.00,'data:image/jpeg;base64,',30000000.00),(19,'106',5000000.00,'TRONG','Đây là căn phòng có diện tích lớn nhất dãy (35m²) tại tầng 3, thiết kế dạng Duplex thông tầng sang trọng. Nội thất được đầu tư bài bản với bàn ăn gia đình, máy nước nóng lạnh trong bathroom,',50,'Lã Xuân Oai',28,4000.00,15000.00,'data:image/jpeg;base64,',5000000.00);
